PRAGMA foreign_keys = ON;
CREATE TABLE properties (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'America/New_York', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE departments (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), UNIQUE(property_id,name));
CREATE TABLE users (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), department_id TEXT REFERENCES departments(id), email TEXT NOT NULL COLLATE NOCASE, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('FRONT_DESK','HOUSEKEEPING','HOUSEKEEPING_SUPERVISOR','MAINTENANCE','MAINTENANCE_MANAGER','MANAGER','ADMIN')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(property_id,email));
CREATE INDEX users_property_active ON users(property_id,active);
CREATE TABLE rooms (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), identifier TEXT NOT NULL, floor TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(property_id,identifier));
CREATE TABLE tasks (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), room_number TEXT, kind TEXT NOT NULL CHECK(kind IN('HOUSEKEEPING_REQUEST','MAINTENANCE_ISSUE','OPERATIONAL_TASK')), priority TEXT NOT NULL CHECK(priority IN('NORMAL','URGENT')), title TEXT NOT NULL, details TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('OPEN','IN_PROGRESS','UNABLE_TO_COMPLETE','COMPLETED','CANCELLED')), assigned_department_id TEXT REFERENCES departments(id), assigned_user_id TEXT REFERENCES users(id), due_at TEXT, started_at TEXT, started_by TEXT REFERENCES users(id), completed_at TEXT, completed_by TEXT REFERENCES users(id), resolution_note TEXT, unable_reason TEXT, unable_note TEXT, cancelled_reason TEXT, source_type TEXT, source_id TEXT, created_by TEXT NOT NULL REFERENCES users(id), updated_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX tasks_property_queue ON tasks(property_id,status,kind,priority,created_at); CREATE INDEX tasks_property_due ON tasks(property_id,due_at,status); CREATE INDEX tasks_assignee ON tasks(property_id,assigned_user_id,status);
CREATE TABLE task_activity (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), task_id TEXT NOT NULL REFERENCES tasks(id), event_type TEXT NOT NULL, actor_user_id TEXT REFERENCES users(id), message TEXT NOT NULL, reason TEXT, created_at TEXT NOT NULL); CREATE INDEX task_activity_task ON task_activity(task_id,created_at);
CREATE TABLE task_comments (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), task_id TEXT NOT NULL REFERENCES tasks(id), author_user_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL, redacted_at TEXT, redacted_by TEXT REFERENCES users(id)); CREATE INDEX task_comments_task ON task_comments(task_id,created_at);
CREATE TABLE task_assignments (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), task_id TEXT NOT NULL REFERENCES tasks(id), from_user_id TEXT REFERENCES users(id), to_user_id TEXT REFERENCES users(id), actor_user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL); CREATE INDEX task_assignments_task ON task_assignments(task_id,created_at);
CREATE TABLE attachments (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, original_filename TEXT NOT NULL, content_type TEXT NOT NULL CHECK(content_type IN('image/jpeg','image/png','image/webp','application/pdf')), size_bytes INTEGER NOT NULL, uploaded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, removed_at TEXT, removed_by TEXT REFERENCES users(id)); CREATE INDEX attachments_entity ON attachments(property_id,entity_type,entity_id);
CREATE TABLE notifications (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), recipient_user_id TEXT REFERENCES users(id), recipient_department_id TEXT REFERENCES departments(id), type TEXT NOT NULL, title TEXT NOT NULL, entity_type TEXT, entity_id TEXT, created_at TEXT NOT NULL, read_at TEXT, archived_at TEXT); CREATE INDEX notifications_user_unread ON notifications(property_id,recipient_user_id,read_at,created_at);
CREATE TABLE recurring_templates (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), title TEXT NOT NULL, description TEXT NOT NULL, department_id TEXT REFERENCES departments(id), assignee_id TEXT REFERENCES users(id), priority TEXT NOT NULL, recurrence_json TEXT NOT NULL, due_offset_minutes INTEGER, checklist_json TEXT, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE recurring_occurrences (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), template_id TEXT NOT NULL REFERENCES recurring_templates(id), scheduled_for TEXT NOT NULL, task_id TEXT NOT NULL REFERENCES tasks(id), created_at TEXT NOT NULL, UNIQUE(template_id,scheduled_for));
CREATE TABLE inspection_templates (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), name TEXT NOT NULL, definition_json TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE inspections (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), template_id TEXT REFERENCES inspection_templates(id), template_snapshot_json TEXT NOT NULL, room_identifier TEXT NOT NULL, inspector_id TEXT NOT NULL REFERENCES users(id), result TEXT CHECK(result IN('PASS','ISSUE')), responses_json TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1); CREATE INDEX inspections_room ON inspections(property_id,room_identifier,created_at);
CREATE TABLE assets (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), asset_code TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL, location TEXT, room_identifier TEXT, serial_reference TEXT, state TEXT NOT NULL CHECK(state IN('ACTIVE','OUT_OF_SERVICE','ARCHIVED')), notes TEXT, pm_frequency_days INTEGER, last_pm_at TEXT, next_pm_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(property_id,asset_code));
CREATE TABLE mod_log_entries (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), author_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL, priority TEXT NOT NULL, body TEXT NOT NULL, room_or_location TEXT, related_task_id TEXT REFERENCES tasks(id), related_incident_id TEXT, follow_up_required INTEGER NOT NULL DEFAULT 0, follow_up_owner_id TEXT REFERENCES users(id), follow_up_due_at TEXT, resolved_at TEXT, resolved_by TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, version INTEGER NOT NULL DEFAULT 1); CREATE INDEX mod_log_property_time ON mod_log_entries(property_id,created_at);
CREATE TABLE calendar_events (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), title TEXT NOT NULL, category TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT, location TEXT, owner_user_id TEXT REFERENCES users(id), department_id TEXT REFERENCES departments(id), notes TEXT, related_type TEXT, related_id TEXT, recurrence_json TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, version INTEGER NOT NULL DEFAULT 1); CREATE INDEX calendar_property_start ON calendar_events(property_id,starts_at);
CREATE TABLE sla_rules (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), task_kind TEXT, category TEXT, priority TEXT, due_minutes INTEGER NOT NULL, due_soon_minutes INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, metadata_json TEXT, created_at TEXT NOT NULL); CREATE INDEX audit_property_time ON audit_events(property_id,created_at); CREATE INDEX audit_entity ON audit_events(property_id,entity_type,entity_id,created_at);
CREATE TABLE legacy_imports (id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id), imported_by TEXT NOT NULL REFERENCES users(id), source_fingerprint TEXT NOT NULL, counts_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(property_id,source_fingerprint));
